#!/usr/bin/env node
/**
 * Bundles the modular plugin source (plugin/src/*) into a single-file Luau
 * plugin script (plugin/dist/GameFlowScanner.server.luau).
 *
 * Why: a single Script can be pasted into Studio and "Save as Local Plugin"
 * with no tooling. The modular source under src/ stays the source of truth;
 * this file is generated.
 *
 * Each ModuleScript is wrapped in a lazy loader and `require(script.Parent.X)`
 * is rewritten to `__require("X")`. `export type` becomes `type` because the
 * wrapped body is no longer at module scope.
 *
 * Usage:
 *   node build/bundle.mjs                       # write dist plugin
 *   node build/bundle.mjs --emit-registry PATH  # also write the loader
 *                                               # prelude (modules only, no
 *                                               # Main) for testing
 */

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const srcDir = join(here, "..", "src");
const distDir = join(here, "..", "dist");

// Registration order is irrelevant (loading is lazy); listed for readability.
const MODULES = [
  "Config",
  "IdGenerator",
  "Classifier",
  "PathResolver",
  "Scanner",
  "Analyzer",
  "Exporter",
  "UI",
];

function rewrite(body) {
  return body
    .replace(/require\(\s*script\.Parent\.(\w+)\s*\)/g, '__require("$1")')
    .replace(/\bexport type\b/g, "type");
}

function moduleBody(name) {
  return readFileSync(join(srcDir, `${name}.luau`), "utf8");
}

function buildRegistry() {
  const parts = [];
  parts.push(`-- Module loader (generated by build/bundle.mjs — do not edit).`);
  parts.push(`local __modules = {}`);
  parts.push(`local __cache = {}`);
  parts.push(`local function __require(name)`);
  parts.push(`\tlocal cached = __cache[name]`);
  parts.push(`\tif cached ~= nil then return cached end`);
  parts.push(`\tlocal loader = __modules[name]`);
  parts.push(`\tif loader == nil then error("module not found: " .. name) end`);
  parts.push(`\tlocal value = loader()`);
  parts.push(`\t__cache[name] = value`);
  parts.push(`\treturn value`);
  parts.push(`end`);
  parts.push("");
  for (const name of MODULES) {
    parts.push(`__modules["${name}"] = function()`);
    parts.push(rewrite(moduleBody(name)));
    parts.push(`end`);
    parts.push("");
  }
  return parts.join("\n");
}

function buildPlugin() {
  const header = [
    "--!nonstrict",
    "--[[",
    "\tGame Flow Scanner — SINGLE-FILE BUILD (generated).",
    "",
    "\tSource of truth: plugin/src/*.luau. Regenerate with:",
    "\t    node plugin/build/bundle.mjs",
    "",
    "\tInstall: paste this into a Script in Studio, right-click it and choose",
    "\t\"Save as Local Plugin\".",
    "]]",
    "",
  ].join("\n");
  const main = rewrite(moduleBody("Main.server"));
  return `${header}\n${buildRegistry()}\n-- ===== Main =====\n${main}\n`;
}

const emitIdx = process.argv.indexOf("--emit-registry");
if (emitIdx !== -1) {
  const out = process.argv[emitIdx + 1];
  writeFileSync(out, buildRegistry() + "\n");
  console.log("wrote registry ->", out);
}

mkdirSync(distDir, { recursive: true });
const dest = join(distDir, "GameFlowScanner.server.luau");
writeFileSync(dest, buildPlugin());
console.log("wrote plugin  ->", dest, `(${(buildPlugin().length / 1024).toFixed(1)} KB)`);
